-- line 13234: tripov (function)
function tripov(speaker, tri, state)
	local humanoid = speaker.Character and speaker.Character:FindFirstChildWhichIsA("Humanoid")
	local root = speaker.Character and getRoot(speaker.Character)
	if not humanoid or not root then return end
	if not state then
		humanoid:ChangeState(Enum.HumanoidStateType.FallingDown)
		root.AssemblyLinearVelocity = root.CFrame.LookVector * tri
	else
		humanoid.PlatformStand = true
		root.AssemblyLinearVelocity = root.CFrame.LookVector * tri
		root.AssemblyAngularVelocity = Vector3.new(0, 0, 4)
		
		task.delay(1.5, function()
			if humanoid and humanoid.Parent then humanoid.PlatformStand = false end
		end)
	end
end

